  `blog_email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `blog_phone` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `blog_keywords` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `blog_description` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `blog_logo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `blog_favicon` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `blog_social` text COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

